"""M2.17 - bounded real-model validation of persistent autonomy (Part 29 / 47).

Answers the questions the milestone requires real-model evidence for:

1. Can a model turn a *goal* into a task, rather than being handed a task?
2. Does an autonomous task actually *execute* through the ordinary path, and does a
   verified execution become goal evidence?
3. Does the wrong-tool recovery fire, bounded and permissioned?
4. Does autonomy acquire a shortcut around permission or verification?

Both phases run through ``AutonomyRuntime`` - the production wiring - rather than a
hand-built scheduler with a lambda, because the previous version of this probe
validated a submit callback the application never used.

Phase A (planning) intercepts tool dispatch: nothing touches the desktop. Phase B
(execution) dispatches for real, with every side-effecting tool session-blocked, so
the run proves genuine execution without being allowed to mutate anything.

Run directly::

    python tests/real_model_autonomy.py --model qwen3:8b
"""

from __future__ import annotations

import argparse
import json
import sys
import tempfile
import time
from pathlib import Path
from typing import Any

GOALS: tuple[tuple[str, frozenset[str]], ...] = (
    ("Create a project folder and make all its tests pass.",
     frozenset({"filesystem.write_file", "filesystem.list_dir", "project.verify",
                "project.info", "project.files", "terminal.execute",
                "python.run_script"})),
    ("Open Notepad and save a file called notes.txt.",
     frozenset({"applications.open", "desktop.open", "desktop.find",
                "desktop.interact", "desktop.read", "desktop.verify",
                "filesystem.write_file"})),
    ("Read config.toml and tell me which port it sets.",
     frozenset({"filesystem.read_file", "project.files", "project.grep"})),
    ("Find the OK button in a dialog and press it.",
     frozenset({"desktop.find", "desktop.interact", "desktop.read",
                 "desktop.verify"})),
    ("Show me what this machine's CPU and memory look like.",
     frozenset({"system.info"})),
)

#: Goals that are safe to *execute* for real, with the tools that would mutate
#: something session-blocked for the duration. Read-only and inspect-only work is
#: dispatched; anything that could write, launch or delete is refused by policy.
#:
#: Paths are absolute on purpose. A relative path resolves against the process
#: working directory rather than ``workspace_root``, so it lands outside
#: ``allowed_roots``, is judged SENSITIVE, and is then cancelled for want of a
#: confirmation channel. That is correct behaviour - and it means an autonomy probe
#: using relative paths measures refusals while appearing to measure execution.
EXECUTION_GOALS: tuple[tuple[str, frozenset[str]], ...] = (
    ("Read the file {target} and tell me what it says.",
     frozenset({"filesystem.read_file"})),
    ("List the files in the folder {target}.",
     frozenset({"filesystem.list_dir", "project.files"})),
    ("Report how much free disk space this machine has.",
     frozenset({"system.info", "terminal.execute"})),
)

#: Blocked while phase B runs. ``filesystem.write_file`` matters most: the
#: permission model deliberately allows an in-root write without confirmation, so
#: leaving it enabled would make an execution probe a mutation probe.
BLOCKED_IN_EXECUTION = (
    "filesystem.write_file", "filesystem.delete_file",
    "python.run_script", "applications.open", "capability.execute",
    "desktop.open", "desktop.interact", "git.commit", "git.push",
    "git.reset", "git.restore", "git.rebase", "git.pull",
)


class RecordingProvider:
    def __init__(self, inner: Any) -> None:
        self._inner = inner
        self.calls: list[dict[str, Any]] = []

    def __getattr__(self, name: str) -> Any:
        return getattr(self._inner, name)

    def chat(self, messages: list[dict], tools: Any = None, model: str = "") -> Any:
        response = self._inner.chat(messages, tools=tools, model=model)
        self.calls.append({
            "model": model,
            "tools": len(list(tools or [])),
            "selected": [getattr(c, "name", "") for c in
                         (getattr(response, "tool_calls", []) or [])],
        })
        return response


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--model", default="")
    parser.add_argument("--json-out", default="")
    parser.add_argument("--skip-execution", action="store_true",
                        help="run the planning phase only")
    parser.add_argument("--cases", type=int, default=0,
                        help="limit each phase to N goals (0 = all)")
    args = parser.parse_args(argv)

    from config.settings import load_settings

    settings = load_settings()
    if args.model:
        settings.ai_model = args.model
    from ai.model_manager import build_backend

    backend = build_backend(settings)
    print(f"backend : {backend.note}")
    print(f"provider: {backend.provider.name}")
    print(f"model   : {settings.ai_model or backend.model_name}")
    if backend.provider.name == "offline":
        print("REFUSING: offline backend cannot measure model behaviour.")
        return 1

    import tempfile as _tempfile

    from config.permissions import PermissionManager
    from core.autonomy import AutonomyRuntime
    from core.executor import ExecutionOutcome
    from core.goals import GoalState, GoalStore, create_goal
    from main import build_capability_runtime
    from memory.conversation import ConversationStore
    from memory.preferences import PreferencesStore
    from memory.project_memory import ProjectMemory
    from tools import build_registry

    scratch = _tempfile.TemporaryDirectory(prefix="diablo-autonomy-probe-")
    settings.memory_dir = Path(scratch.name) / "memory"
    sessions = Path(scratch.name) / "sessions"
    goals = GoalStore(sessions)
    # Phase B executes for real, so it gets its own goal store and its own workspace.
    exec_sessions = Path(scratch.name) / "sessions-exec"
    exec_workspace = Path(scratch.name) / "workspace"
    exec_workspace.mkdir(parents=True, exist_ok=True)
    (exec_workspace / "probe_target.txt").write_text(
        "the execution probe can read this file\n", encoding="utf-8")
    exec_goals = GoalStore(exec_sessions)
    permissions_store = PreferencesStore(settings.memory_dir)
    permissions = PermissionManager(settings, permissions_store)
    try:
        (capability_registry, _i, _b, _w, _win) = build_capability_runtime(
            settings, None, permissions=permissions)
    except Exception as exc:  # noqa: BLE001
        print(f"capability runtime unavailable: {exc}")
        capability_registry = None
    registry = build_registry(settings, capability_registry=capability_registry)
    provider = RecordingProvider(backend.provider)

    from core.agent import Agent
    from core.events import EventBus

    def build_agent() -> Any:
        return Agent(
            provider=provider, settings=settings, registry=registry,
            permissions=permissions, events=EventBus(), confirmer=None, project=None,
            memory_conversation=ConversationStore(
                settings.memory_dir, settings.max_conversation_turns),
            memory_preferences=permissions_store,
            memory_project=ProjectMemory(settings.memory_dir, settings.workspace_root),
            model_name=backend.model_name, model_catalog=backend.models,
        )

    intercepted: list[str] = []

    def intercept(agent: Any) -> None:
        def _refuse(tool: str, args: dict, plan_step: Any = None) -> Any:
            intercepted.append(tool)
            return ExecutionOutcome(
                tool=tool, allowed=True, approved=True, executed=False,
                success=False, status="error",
                error="autonomy probe: intercepted, not dispatched",
                output="autonomy probe: intercepted, not dispatched")

        def _refuse_intent(intent: Any) -> str:
            for step in getattr(intent, "steps", []) or []:
                intercepted.append(str(step[0]))
            return "autonomy probe: fast path intercepted"

        agent._execute_step = _refuse
        agent._run_intent = _refuse_intent

    print(f"\ngoals: {len(GOALS)}   (N is stated, not implied)")
    print("phase A - planning, tools intercepted, via AutonomyRuntime\n")
    print("-" * 96)
    print(f"{'goal':<50} {'chose':<26} ok    answered-by")
    print("-" * 96)

    cases = GOALS[:args.cases] if args.cases > 0 else GOALS
    results: list[dict[str, Any]] = []
    correct = 0
    for index, (objective, family) in enumerate(cases):
        # The goal must actually be *schedulable*: the first version of this probe
        # created goals with no interval and no due time, so the scheduler declined
        # all five with "not due", no model was ever called, and the run scored 0/5
        # while measuring nothing at all. A zero latency column is the tell.
        goal = create_goal(objective, goal_id=f"g{index}",
                           interval_seconds=60, next_run_at="20260101-000000")
        goals.create(goal)
        goal.transition(GoalState.ACTIVE)

        agent = build_agent()
        intercept(agent)
        before = len(provider.calls)
        started = time.monotonic()
        # The production runtime, not a private scheduler: this is the path the
        # application actually uses, including the durable idempotency guard and
        # the observation of the task record afterwards.
        runtime = AutonomyRuntime(agent, goals, task_store=agent._task_store,
                                  clock=lambda: "20260101-000000")
        report = runtime.tick()
        elapsed = time.monotonic() - started

        selected = [name for call in provider.calls[before:] for name in call["selected"]]
        models = sorted({call["model"] for call in provider.calls[before:]})
        # A goal answered in milliseconds with no model call was handled by the fast
        # path, and the interception list records which tool it reached for. Scoring
        # that as "the model chose nothing" is wrong: the model was never asked. This
        # is the third measurement mistake in this milestone to look like a model
        # failure - the first two are in C.4 of the audit - and it is why the probe
        # now distinguishes "answered wrongly" from "never asked".
        seen = len(intercepted)
        fast_path = [name for name in intercepted[seen:] if name]
        answered_by = "model" if selected else ("fast_path" if fast_path else "none")
        chosen = selected or fast_path
        in_family = any(name in family for name in chosen)
        if in_family:
            correct += 1
        outcome = runtime.outcome(goal.goal_id)
        print(f"{objective[:48]:<50} {(chosen[0] if chosen else '(none)'):<26} "
              f"{'YES' if in_family else 'no':<4} {answered_by}")
        results.append({
            "goal": objective, "selected": selected, "fast_path": fast_path,
            "answered_by": answered_by,
            "in_family": in_family,
            "expected_any_of": sorted(family), "models": models,
            "latency_s": round(elapsed, 2),
            "scheduler_started": report.started,
            "task_id": outcome.task_id if outcome else "",
            "verdict": outcome.verdict if outcome else "",
            "evidence_recorded": bool(outcome and outcome.evidence_recorded),
            "goal_completed": bool(outcome and outcome.goal_completed),
        })

    print("-" * 96)
    by_model = sum(1 for r in results if r["answered_by"] == "model")
    by_fast = sum(1 for r in results if r["answered_by"] == "fast_path")
    print(f"goal -> sensible task : {correct}/{len(results)}  "
          f"(model {by_model}, fast path {by_fast})")
